        function bindEntryTreeToggleV575() {
          const btn = $("treeToggleBtn");
          if (!btn || btn.__treeToggleV575) return;
          btn.__treeToggleV575 = true;
          const isIOS =
            /iPad|iPhone|iPod/i.test(navigator.userAgent || "") ||
            (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
          let gesture = null,
            lastAt = 0;
          const stop = (ev) => {
            try {
              if (ev.cancelable) ev.preventDefault();
            } catch (e) {}
            try {
              ev.stopPropagation();
              ev.stopImmediatePropagation();
            } catch (e) {}
          };
          if (isIOS && window.PointerEvent) {
            btn.addEventListener(
              "pointerdown",
              (ev) => {
                if (ev.pointerType === "mouse") return;
                gesture = {
                  id: ev.pointerId,
                  x: ev.clientX,
                  y: ev.clientY,
                  moved: false,
                };
              },
              { capture: true, passive: true },
            );
            btn.addEventListener(
              "pointermove",
              (ev) => {
                if (
                  gesture &&
                  gesture.id === ev.pointerId &&
                  (Math.abs(ev.clientX - gesture.x) > 12 ||
                    Math.abs(ev.clientY - gesture.y) > 12)
                )
                  gesture.moved = true;
              },
              { capture: true, passive: true },
            );
            btn.addEventListener(
              "pointercancel",
              () => {
                gesture = null;
              },
              { capture: true, passive: true },
            );
            btn.addEventListener(
              "pointerup",
              (ev) => {
                const g = gesture;
                gesture = null;
                if (!g || g.id !== ev.pointerId || g.moved) return;
                lastAt = Date.now();
                stop(ev);
                toggleEntryTreePanelV575();
              },
              { capture: true, passive: false },
            );
            btn.addEventListener(
              "click",
              (ev) => {
                if (Date.now() - lastAt < 900) return stop(ev);
                lastAt = Date.now();
                stop(ev);
                toggleEntryTreePanelV575();
              },
              { capture: true, passive: false },
            );
          } else if (isIOS) {
            btn.addEventListener(
              "touchstart",
              (ev) => {
                const t = ev.touches && ev.touches[0];
                gesture = t
                  ? { x: t.clientX, y: t.clientY, moved: false }
                  : null;
              },
              { capture: true, passive: true },
            );
            btn.addEventListener(
              "touchmove",
              (ev) => {
                const t = ev.touches && ev.touches[0];
                if (
                  gesture &&
                  t &&
                  (Math.abs(t.clientX - gesture.x) > 12 ||
                    Math.abs(t.clientY - gesture.y) > 12)
                )
                  gesture.moved = true;
              },
              { capture: true, passive: true },
            );
            btn.addEventListener(
              "touchcancel",
              () => {
                gesture = null;
              },
              { capture: true, passive: true },
            );
            btn.addEventListener(
              "touchend",
              (ev) => {
                const g = gesture;
                gesture = null;
                if (!g || g.moved) return;
                lastAt = Date.now();
                stop(ev);
                toggleEntryTreePanelV575();
              },
              { capture: true, passive: false },
            );
            btn.addEventListener(
              "click",
              (ev) => {
                if (Date.now() - lastAt < 900) return stop(ev);
                lastAt = Date.now();
                stop(ev);
                toggleEntryTreePanelV575();
              },
              { capture: true, passive: false },
            );
          } else btn.addEventListener("click", toggleEntryTreePanelV575);
        }
