            if (
              !rec ||
              !count ||
              state.settings.barcodeControlEnabled === false ||
              count % every !== 0
            )
              return;
            const token =
              "v445|" + count + "|" + String(rec.id || rec.barcode || "");
            const key = "mesaha_v442_milestone_token";
            if (localStorage.getItem(key) === token) return;
            localStorage.setItem(key, token);
            let wrap = document.getElementById("mesahaBarcodeMiniV440");
            if (!wrap) {
              wrap = document.createElement("div");
              wrap.id = "mesahaBarcodeMiniV440";
              wrap.className = "hidden";
              wrap.innerHTML =
                '<div class="bc440-card"><button type="button" class="bc440-close" aria-label="Kapat">×</button><b class="bc440-title">' +
                count +
                '. kayıt kontrolü</b><div class="bc440-barcode" id="bc440Barcode">-</div><div class="bc440-meta" id="bc440Meta">-</div></div>';
              document.body.appendChild(wrap);
              wrap
                .querySelector(".bc440-close")
                .addEventListener("click", () => wrap.classList.add("hidden"));
            }
            const p = productInfo(rec.productType);
            wrap.className = "product-" + (p && p.cls ? p.cls : "tomruk");
